# ShapefunctionsQ4xi.py
# Python version of ShapefunctionsQ4xi.m (generated by the Symbolic Math Toolbox)
# Bilinear shape functions of the Q4 element in natural coordinates xi, eta.

import numpy as np

def ShapefunctionsQ4xi(Lx, Ly, xi, eta):
    t2 = eta/4.0
    t3 = xi/4.0
    t7 = eta*xi*(-1.0/4.0)
    t4 = t2*xi
    t5 = -t2
    t6 = -t3
    Nvec = np.array([t4+t5+t6+1.0/4.0, t3+t5+t7+1.0/4.0, t2+t3+t4+1.0/4.0, t2+t6+t7+1.0/4.0])
    return Nvec
